import { Component, OnInit, Input } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { ApiService } from '../../core/services/api.service';
import { ToastService } from '../../core/services/toast.service';

@Component({
  selector: 'app-project-detail',
  standalone: true,
  imports: [CommonModule, RouterModule],
  template: `
    <div class="page-container">
      <div class="page-header">
        <a routerLink="/projects" style="font-size:12px;color:var(--text-muted);">← Retour aux projets</a>
        <div style="display:flex;align-items:center;justify-content:space-between;margin-top:8px;">
          <h1 class="page-title">// {{project?.name || 'Projet'}}</h1>
          <div class="live-indicator" *ngIf="project">
            <div class="live-dot"></div>
            Santé : <strong [style.color]="getHealthColor(project.healthScore)">
              {{project.healthScore | number:'1.0-0'}}%
            </strong>
          </div>
        </div>
      </div>

      <div *ngIf="loading" class="loading-overlay"><div class="spinner"></div></div>

      <ng-container *ngIf="project && !loading">
        <!-- Stats -->
        <div class="kpi-grid" style="margin-bottom:16px;">
          <div class="kpi-card red">
            <div class="kpi-label">Incidents ouverts</div>
            <div class="kpi-value">{{project.openIncidents || 0}}</div>
          </div>
          <div class="kpi-card blue">
            <div class="kpi-label">En analyse</div>
            <div class="kpi-value">{{project.analyzingIncidents || 0}}</div>
          </div>
          <div class="kpi-card orange">
            <div class="kpi-label">Corrections proposées</div>
            <div class="kpi-value">{{project.proposedIncidents || 0}}</div>
          </div>
          <div class="kpi-card green">
            <div class="kpi-label">Résolus</div>
            <div class="kpi-value">{{project.resolvedIncidents || 0}}</div>
          </div>
        </div>

        <!-- Info + Incidents -->
        <div class="grid-2">
          <div class="card">
            <div class="card-header"><span class="card-title">Informations</span></div>
            <table style="width:100%;">
              <tr *ngFor="let info of getInfoRows()">
                <td style="font-size:11px;color:var(--text-faint);padding:7px 0;width:40%;">{{info.label}}</td>
                <td style="font-size:12px;color:var(--text-secondary);font-family:var(--font-mono);">{{info.value}}</td>
              </tr>
            </table>
          </div>

          <div class="card">
            <div class="card-header">
              <span class="card-title">Incidents récents</span>
              <a [routerLink]="['/incidents']" [queryParams]="{projectId: project.id}"
                 class="btn btn-secondary btn-sm">Voir tous →</a>
            </div>
            <div *ngFor="let inc of incidents.slice(0,6)" class="inc-row">
              <span class="badge {{inc.severity?.toLowerCase()}}">{{inc.severity}}</span>
              <span style="flex:1;font-size:11px;color:var(--text-secondary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">
                {{inc.title || inc.sourceType}}
              </span>
              <span class="badge {{inc.status?.toLowerCase()}}">{{inc.status}}</span>
            </div>
            <div *ngIf="incidents.length === 0" class="empty-state" style="padding:20px;">
              <div class="empty-title">Aucun incident</div>
            </div>
          </div>
        </div>
      </ng-container>
    </div>
  `,
  styles: [`
    .inc-row {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 8px 0;
      border-bottom: 1px solid var(--border);
      &:last-child { border-bottom: none; }
    }
  `]
})
export class ProjectDetailComponent implements OnInit {
  @Input() id!: string;
  project: any   = null;
  incidents: any[] = [];
  loading = true;

  constructor(private api: ApiService, private toast: ToastService) {}

  ngOnInit() {
    this.api.getProject(this.id).subscribe({
      next: p => { this.project = p; this.loading = false; this.loadIncidents(); },
      error: () => { this.toast.error('Erreur', 'Projet introuvable'); this.loading = false; }
    });
  }

  loadIncidents() {
    this.api.getIncidents({ projectId: this.id, size: 10 }).subscribe((r: any) => {
      this.incidents = r.content || r;
    });
  }

  getInfoRows() {
    if (!this.project) return [];
    return [
      { label: 'ID',          value: this.project.id },
      { label: 'Créé le',     value: new Date(this.project.createdAt).toLocaleDateString('fr-FR') },
      { label: 'Clé Sonar',   value: this.project.sonarKey || '—' },
      { label: 'Description', value: this.project.description || '—' },
    ];
  }

  getHealthColor(score: number) {
    if (score >= 80) return 'var(--accent-green)';
    if (score >= 60) return 'var(--accent-orange)';
    return 'var(--accent-red)';
  }
}
